  /** Tolerance used when comparing the similarity score (a double). */
  private static final double SCORE_TOLERANCE = 0.01;

  /**
   * Two sequences that share a non-trivial proportion of characters yield a
   * high (but below 1.0) similarity score. Here a 2-character buffer is
   * compared against a 6-character buffer, both filled with the default
   * '�' characters.
   */
  @Test(timeout = 4000)
  public void testApply_partiallyMatchingSequences_returnsHighScore() throws Throwable {
      JaroWinklerSimilarity similarity = JaroWinklerSimilarity.INSTANCE;
      CharBuffer shortBuffer = CharBuffer.allocate(2);
      CharBuffer longBuffer = CharBuffer.wrap(new char[6]);

      Double score = similarity.apply((CharSequence) shortBuffer, (CharSequence) longBuffer);

      assertEquals(0.8222222222222222, (double) score, SCORE_TOLERANCE);
  }

  /**
   * When one of the inputs is an empty sequence, no characters can match, so
   * the similarity score is 0.0. The empty buffer here is produced by wrapping
   * a buffer at an offset equal to its length.
   */
  @Test(timeout = 4000)
  public void testApply_emptySequence_returnsZero() throws Throwable {
      JaroWinklerSimilarity similarity = JaroWinklerSimilarity.INSTANCE;
      CharBuffer nonEmptyBuffer = CharBuffer.allocate(2);
      CharBuffer emptyBuffer = CharBuffer.wrap((CharSequence) nonEmptyBuffer, 2, 2);

      Double score = similarity.apply((CharSequence) emptyBuffer, (CharSequence) nonEmptyBuffer);

      assertEquals(0.0, (double) score, SCORE_TOLERANCE);
  }

  /**
   * Comparing sequences of very different lengths (8 vs. 1772 characters) still
   * produces a defined similarity score driven by the shared characters.
   */
  @Test(timeout = 4000)
  public void testApply_sequencesOfVeryDifferentLengths_returnsExpectedScore() throws Throwable {
      JaroWinklerSimilarity similarity = JaroWinklerSimilarity.INSTANCE;
      CharBuffer shortBuffer = CharBuffer.wrap(new char[8]);
      CharBuffer longBuffer = CharBuffer.allocate(1772);

      Double score = similarity.apply((CharSequence) longBuffer, (CharSequence) shortBuffer);

      assertEquals(0.6681715575620767, (double) score, SCORE_TOLERANCE);
  }

  /**
   * Passing {@code null} for both inputs is rejected with an
   * IllegalArgumentException ("CharSequences must not be null").
