  /**
   * {@code matches} returns the [matches, half-transpositions, prefix] triple.
   * The two sequences each contain a single 'f' but at different positions
   * (index 1 vs. index 3), giving 6 matched characters, 2 half-transpositions
   * and a common prefix length of 1.
   */
  @Test(timeout = 4000)
  public void testMatches_sameCharAtDifferentPositions_returnsTriple() throws Throwable {
      char[] firstChars = new char[8];
      firstChars[1] = 'f';
      CharBuffer firstBuffer = CharBuffer.wrap(firstChars);

      char[] secondChars = new char[6];
      secondChars[3] = 'f';
      CharBuffer secondBuffer = CharBuffer.wrap(secondChars);

      int[] result = JaroWinklerSimilarity.matches(secondBuffer, firstBuffer);

      assertArrayEquals(new int[] {6, 2, 1}, result);
  }

  /**
