  public void testMatches_noOverlappingCharacters_returnsZeros() throws Throwable {
      char[] sharedChars = new char[12];
      CharBuffer overwrittenBuffer = CharBuffer.wrap(sharedChars);
      overwrittenBuffer.put("X19l5(mgJ");
      CharBuffer originalBuffer = CharBuffer.wrap(sharedChars);

      int[] result = JaroWinklerSimilarity.matches(originalBuffer, overwrittenBuffer);

      assertArrayEquals(new int[] {0, 0, 0}, result);
  }

