  public void testApply_identicalInputs_returnsOne() throws Throwable {
      JaroWinklerSimilarity similarity = JaroWinklerSimilarity.INSTANCE;
      CharBuffer buffer = CharBuffer.allocate(2);

      Double score = similarity.apply((CharSequence) buffer, (CharSequence) buffer);

      assertEquals(1.0, (double) score, SCORE_TOLERANCE);
  }

